import './style.css';
import {languageTag,setLanguage,languageSelector,translateDOM,t} from './i18n';
import {type Vault,type Vehicle,type Folder,type Part,type Service,type Attachment,type Fill,emptyVault,demoVault,uid,today,due,fuelStats,partTemplates,vaultSchema,vehicleSchema,partSchema,serviceSchema,fillSchema} from './domain';
import {deriveKey,encryptVault,decryptVault,toB64,fromB64} from './crypto';
import * as storage from './storage';
import {validateGLB} from './glb';
const root=document.querySelector<HTMLDivElement>('#app')!;
const esc=(x:unknown)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const n=(x:number)=>new Intl.NumberFormat(languageTag(),{maximumFractionDigits:0}).format(x);
const money=(x:number)=>new Intl.NumberFormat(languageTag(),{style:'currency',currency:'EUR'}).format(x);
const date=(x:string)=>new Intl.DateTimeFormat(languageTag(),{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(x+'T00:00:00Z'));
const icon=(name:string)=>{const paths:Record<string,string>={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',car:'<path d="m5 7 2-4h10l2 4 2 3v8H3v-8zM3 10h18M7 14h.01M17 14h.01M5 18v3M19 18v3"/>',wrench:'<path d="m14 7 3 3 4-4a7 7 0 0 1-9 9l-6 6-3-3 6-6a7 7 0 0 1 9-9z"/>',book:'<path d="M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1zm0 0v15"/>',fuel:'<path d="M3 21V3h10v18M2 21h12M3 10h10M16 4l4 4v9a2 2 0 0 1-4 0v-4h-3M17 5v4h3"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2.5"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',plus:'<path d="M12 4v16M4 12h16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 3v4l4 3 3-1 3 1 4-3v-4l2-3-2-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',file:'<path d="M14 2H5v20h14V7zm0 0v5h5M8 12h8M8 16h6"/>',chart:'<path d="M3 3v18h18M7 16l4-6 4 3 6-8"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',bell:'<path d="M5 9a7 7 0 0 1 14 0v7l2 2H3l2-2zM9 21h6"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]??paths.car}</svg>`;};
const button=(action:string,label:string,ic='plus',cls='primary',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${icon(ic)}${label}</button>`;
const field=(label:string,name:string,value:unknown='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const area=(label:string,name:string,value='')=>`<label class="field full">${label}<textarea name="${name}" maxlength="2000" rows="3">${esc(value)}</textarea></label>`;
const select=(label:string,name:string,options:{value:string;label:string}[],value='')=>`<label class="field">${label}<select name="${name}">${options.map(o=>`<option value="${esc(o.value)}" ${o.value===value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label>`;
let vault:Vault|null=null,key:CryptoKey|null=null,salt:Uint8Array|null=null,envelope:string|null=null;
let selected='',folderViewId='',page='dashboard',demo=false,search='',filter='all',loading=false,saveError=false,session=0;
let renderVersion=0;
let cleanupViewer:(()=>void)|null=null,saveQueue:Promise<unknown>=Promise.resolve();
let catalogue:{vehicles:CatalogueRow[];retrieved:string;count:number}|null=null;
interface CatalogueRow{id:string;make:string;model:string;version:string;energy:string;cc:number|null;kw:number|null;fiscal:number|null;gearbox:string;gears:number|null;body:string;wltp:number|null;}
const vehicle=()=>vault?.vehicles.find(v=>v.id===selected)??vault?.vehicles[0];
const parts=()=>vault!.parts.filter(p=>p.vehicleId===vehicle()?.id);
const services=()=>vault!.services.filter(p=>p.vehicleId===vehicle()?.id).sort((a,b)=>b.date.localeCompare(a.date)||b.km-a.km);
const fills=()=>vault!.fills.filter(p=>p.vehicleId===vehicle()?.id);
function toast(message:string,error=false){message=t(message);document.querySelector('.toast')?.remove();const notice=document.createElement('div');notice.className='toast'+(error?' error':'');notice.setAttribute('role',error?'alert':'status');notice.textContent=message;document.body.append(notice);setTimeout(()=>notice.remove(),6500);}
function errorText(e:unknown){if(e instanceof Error&&e.name==='ZodError')return 'Données invalides : vérifiez les dates, montants et kilométrages.';return e instanceof Error?e.message:typeof e==='string'?e:'Une erreur est survenue.';}
function setStatus(text:string,bad=false){const el=document.querySelector('#save-status');if(el){el.textContent=t(text);el.classList.toggle('bad',bad);}}
async function commit(next:Vault){
 const parsed=vaultSchema.parse(next);if(demo){vault=parsed;return;}
 if(!key||!salt)throw Error('Le coffre est verrouillé.');
 const k=key,s=salt,token=session;
 setStatus('Enregistrement…');
 const task=saveQueue.catch(()=>{}).then(async()=>{const encrypted=await encryptVault(parsed,k,s);await storage.save(encrypted);if(token===session){envelope=encrypted;vault=parsed;saveError=false;setStatus('Enregistré · chiffré');}});
 saveQueue=task;
 try{await task;}catch(e){saveError=true;setStatus('Échec de l’enregistrement',true);throw e;}
}
async function mutate(fn:(v:Vault)=>void){if(!vault)throw Error('Coffre verrouillé.');const next=structuredClone(vault);fn(next);await commit(next);}
function destroyView(){renderVersion++;cleanupViewer?.();cleanupViewer=null;}
function renderGate(failure=''){
 destroyView();document.querySelector('dialog')?.remove();root.innerHTML=`<main class="gate"><div class="gate-brand"><span class="logo">${icon('wrench')}</span>JMeca<span class="beta">BÊTA 0.1</span>${languageSelector()}</div><div class="gate-grid"><section><div class="eyebrow">VOTRE GARAGE, EN MIEUX.</div><h1>Prenez soin de<br>ce qui vous emmène.</h1><p>Entretien, pièces, factures et carburant.<br>Tout votre véhicule, au même endroit.</p><div class="gate-points"><span>${icon('check')}Vos données restent sur cet appareil</span><span>${icon('lock')}Coffre personnel chiffré</span><span>${icon('car')}Windows · macOS · Linux</span></div><div class="gate-note">Un carnet qui vous appartient. Sans compte, sans publicité.</div></section><section class="gate-card"><span class="lock-mark">${icon('lock')}</span><h2>${envelope?'Heureux de vous revoir.':'Bienvenue dans votre garage.'}</h2><p>${envelope?'Déverrouillez votre coffre personnel.':'Créez le mot de passe qui protège votre coffre.'}</p><form id="unlock-form">${field('Mot de passe','password','','password',`required minlength="${envelope?1:12}" maxlength="256" autocomplete="${envelope?'current-password':'new-password'}" autofocus`)}${!envelope?field('Confirmez le mot de passe','confirm','','password','required minlength="12" maxlength="256" autocomplete="new-password"'):''}<p class="hint">${envelope?'Votre mot de passe ne quitte jamais cet appareil.':'12 caractères minimum. Conservez ce mot de passe : il ne peut pas être récupéré.'}</p><p class="form-error" role="alert">${esc(failure)}</p><button class="btn primary wide" type="submit">${icon('lock')}${envelope?'Ouvrir mon garage':'Créer mon coffre'}</button></form><div class="separator">ou découvrir JMeca</div>${button('demo','Explorer la démonstration','arrow','secondary wide')}${button('restore-gate','Restaurer une sauvegarde','download','text wide')}<p class="tiny">${storage.native?'Application de bureau · stockage local':'Aperçu navigateur · coffre séparé de l’application de bureau'}</p></section></div></main>`;
 translateDOM(root);
 document.querySelector('#unlock-form')!.addEventListener('submit',async e=>{e.preventDefault();if(loading)return;const form=e.currentTarget as HTMLFormElement,d=new FormData(form),password=String(d.get('password'));if(!envelope&&password!==d.get('confirm')){(form.querySelector('.form-error') as HTMLElement).textContent='Les mots de passe ne correspondent pas.';return;}loading=true;const submit=form.querySelector('button')!;submit.disabled=true;submit.textContent='Ouverture du coffre…';try{if(envelope){const result=await decryptVault(envelope,password);vault=result.vault;key=result.key;salt=result.salt;}else{salt=crypto.getRandomValues(new Uint8Array(16));key=await deriveKey(password,salt);await commit(emptyVault());}form.reset();selected=vault!.vehicles[0]?.id??'';demo=false;session++;lastActivity=Date.now();render();}catch(e){renderGate(errorText(e));}finally{loading=false;}});
}
const navItems=[['dashboard','grid','Vue d’ensemble'],['folders','file','Dossiers & parc'],['parts','wrench','Pièces & échéances'],['book','book','Carnet d’entretien dématérialisé'],['fuel','fuel','Consommation'],['stations','pin','Stations-service'],['knowledge','search','Base véhicules']];
function render(){
 if(!vault)return renderGate();destroyView();const v=vehicle();if(v)selected=v.id;
 const alerts=v?parts().filter(p=>due(p,v.odometer,today(),vault!.settings.leadDays,vault!.settings.leadKm).status!=='ok').length:0;
 root.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#" data-action="nav" data-page="dashboard"><span class="logo">${icon('wrench')}</span>JMeca<span class="beta">BÊTA</span></a><div class="sidebar-label">MON ESPACE</div><nav>${navItems.map(([id,ic,label])=>`<button class="nav-item ${page===id?'active':''}" data-action="nav" data-page="${id}">${icon(ic)}<span>${label}</span>${id==='parts'&&alerts?`<b>${alerts}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="private-note">${icon('lock')}<div><strong>${demo?'Mode découverte':'Votre garage est privé'}</strong><span>${demo?'Aucune donnée enregistrée':'Chiffrement local · sans cloud'}</span></div></div><button class="nav-item ${page==='settings'?'active':''}" data-action="nav" data-page="settings">${icon('settings')}Paramètres & sauvegardes</button><button class="nav-item" data-action="lock">${icon('lock')}${demo?'Quitter la démo':'Verrouiller le coffre'}</button><div class="sidebar-version">JMeca 0.1.1 · Fait pour durer.</div></div></aside><div class="main-shell">${demo?'<div class="demo-banner">MODE DÉMONSTRATION · Véhicule et interventions fictifs. Les modifications sont temporaires.<button data-action="lock">Créer mon coffre →</button></div>':''}<header class="topbar"><div class="breadcrumb">Mon garage <span>/</span> <strong>${esc(navItems.find(x=>x[0]===page)?.[2]??'Paramètres')}</strong></div><div class="top-actions">${languageSelector()}<span class="save-dot ${saveError?'bad':''}"></span><span id="save-status">${demo?'Démonstration':saveError?'Échec de l’enregistrement':'Enregistré · chiffré'}</span><button class="icon-btn" title="Voir les échéances" aria-label="Voir les échéances" data-action="nav" data-page="parts">${icon('bell')}${alerts?'<i></i>':''}</button><span class="avatar">JM</span></div></header><main class="content">${renderPage(v)}</main><footer>JMeca · Votre historique, votre tranquillité.<span>${storage.native?'Stockage sur cet ordinateur':'Aperçu navigateur'}${demo?' · Démonstration':''}</span></footer></div></div>`;
 translateDOM(root);
 if(v&&page==='dashboard'){const host=document.querySelector<HTMLElement>('#car-viewer');if(host){const token=renderVersion;void import('./viewer').then(({mountViewer})=>{if(token===renderVersion&&host.isConnected)cleanupViewer=mountViewer(host,v);}).catch(()=>{if(host.isConnected)host.textContent='Aperçu 3D indisponible.';});}}
 if(page==='knowledge')void loadCatalogue();
 if(page==='stations')bindStations();
 bindFilters();
}
function title(eyebrow:string,name:string,description:string,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(name)}</h1><p>${esc(description)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function empty(title:string,detail:string,action='add-vehicle',label='Ajouter un véhicule'){return `<div class="empty-state">${icon('car')}<h2>${title}</h2><p>${detail}</p>${button(action,label)}</div>`;}
function vehicleSelect(){return `<div class="vehicle-switch">${icon('car')}<select id="vehicle-select" aria-label="Véhicule actif">${vault!.vehicles.map(v=>`<option value="${esc(v.id)}" ${v.id===selected?'selected':''}>${esc(v.make+' '+v.model)} · ${v.year}</option>`).join('')}</select></div>`;}
function renderPage(v:Vehicle|undefined):string{
 if(page==='folders')return foldersPage();
 if(page==='knowledge')return title('LE BON POINT DE DÉPART','Trouvez votre véhicule.','Un catalogue hors ligne de versions et motorisations, issu des données ouvertes ADEME.',button('add-vehicle','Ajout manuel'))+`<div class="search-bar">${icon('search')}<input id="catalogue-search" placeholder="Marque, modèle, moteur… ex. Renault Clio" value="${esc(search)}" aria-label="Rechercher dans le catalogue"></div><div id="catalogue-results"><p class="muted">Chargement du catalogue…</p></div>`;
 if(page==='settings')return settingsPage();
 if(page==='stations')return stationsPage();
 if(!v)return title('BIENVENUE CHEZ VOUS','Votre garage prend vie.','Ajoutez votre premier véhicule pour commencer à suivre son entretien.')+empty('Chaque trajet a une histoire.','Retrouvez-la ici, pièce après pièce.')+`<div class="two-cards"><article class="panel"><h3>À partir du catalogue</h3><p>Recherchez votre marque, votre modèle et sa version.</p>${button('nav','Explorer les véhicules','search','secondary','data-page="knowledge"')}</article><article class="panel"><h3>Vous gardez la main</h3><p>Ajout manuel, rappels personnalisés et pièces jointes chiffrées.</p></article></div>`;
 if(page==='dashboard')return dashboard(v);
 if(page==='parts')return partsPage(v);
 if(page==='book')return bookPage(v);
 if(page==='fuel')return fuelPage(v);
 return '';
}
function dueLabel(p:Part,v:Vehicle){const d=due(p,v.odometer,today(),vault!.settings.leadDays,vault!.settings.leadKm);return `<span class="badge ${d.status}">${d.status==='overdue'?'À faire':d.status==='soon'?'Bientôt':'À jour'}</span>`;}
function remaining(p:Part,v:Vehicle){const d=due(p,v.odometer);return `<div class="remaining">${d.km!==null?`<strong class="${d.km<=0?'red':''}">${d.km<=0?n(Math.abs(d.km))+' km dépassés':n(d.km)+' km restants'}</strong>`:''}${d.days!==null?`<span>${d.days<0?Math.abs(d.days)+' j de retard':d.days===0?'Aujourd’hui':'Dans '+d.days+' jours'} · ${date(d.date!)}</span>`:''}</div>`;}
function dashboard(v:Vehicle){
 const p=parts();const upcoming=[...p].sort((a,b)=>{const da=due(a,v.odometer),db=due(b,v.odometer);return Math.min(da.days??Infinity,(da.km??Infinity)/35)-Math.min(db.days??Infinity,(db.km??Infinity)/35);}).slice(0,3);
 const attention=p.filter(x=>due(x,v.odometer,today(),vault!.settings.leadDays,vault!.settings.leadKm).status!=='ok').length;const stats=fuelStats(fills()),cost=services().reduce((a,s)=>a+s.cost,0);
 return title('LE PLAISIR DE ROULER SEREIN','Votre garage, en un coup d’œil.','Un peu d’attention aujourd’hui. Beaucoup de kilomètres demain.',button('add-vehicle','Ajouter un véhicule','plus','secondary'))+`<div class="dashboard-grid"><section class="vehicle-hero"><div class="hero-top"><span class="hero-label">MON VÉHICULE</span>${vehicleSelect()}</div><div class="hero-copy"><div class="hero-year">${v.year} <span>•</span> ${esc(v.energy)}</div><h2>${esc(v.make)} <strong>${esc(v.model)}</strong></h2><p>${esc(v.version)}</p><span class="registration">${esc(v.registration||'Immatriculation non renseignée')}</span></div><div id="car-viewer" class="car-viewer" role="img" aria-label="Modèle 3D du véhicule, glisser pour tourner"></div><span class="viewer-caption">${t(`VUE 3D INTERACTIVE · SILHOUETTE ${v.customModel?'IMPORTÉE':'GÉNÉRIQUE'}`)}</span><div class="hero-bottom"><div><span>KILOMÉTRAGE ACTUEL</span><strong>${n(v.odometer)} <small>km</small></strong></div>${button('mileage','Mettre à jour','plus','hero-button')}${button('edit-vehicle','Fiche véhicule','arrow','hero-link')}</div></section><section class="health-card"><div class="card-kicker">${icon('wrench')} L’ESPRIT TRANQUILLE</div><div class="health-orbit"><span>${p.length-attention}<small>/${p.length}</small></span><div>suivis à jour</div></div><h3>${!p.length?'On commence le suivi ?':attention?'Un peu d’attention à prévoir.':'Prêt pour la route.'}</h3><p>${!p.length?'Ajoutez vos pièces et leurs périodicités.':attention?`${attention} échéance${attention>1?'s':''} à vérifier sur votre véhicule.`:'Aucune échéance proche selon vos rappels.'}</p>${button('nav','Consulter les échéances','arrow','text','data-page="parts"')}</section></div><div class="stats-grid"><article class="stat-card"><span class="stat-icon amber">${icon('clock')}</span><div><span>À surveiller</span><strong>${attention}<small> échéance${attention>1?'s':''}</small></strong></div></article><article class="stat-card"><span class="stat-icon teal">${icon('fuel')}</span><div><span>Consommation moyenne</span><strong>${stats.average===null?'—':new Intl.NumberFormat(languageTag(),{minimumFractionDigits:1,maximumFractionDigits:1}).format(stats.average)}<small> L/100 km</small></strong></div></article><article class="stat-card"><span class="stat-icon blue">${icon('chart')}</span><div><span>Entretien enregistré</span><strong>${money(cost)}</strong></div></article><article class="stat-card"><span class="stat-icon violet">${icon('book')}</span><div><span>Votre carnet</span><strong>${services().length}<small> intervention${services().length>1?'s':''}</small></strong></div></article></div><section class="panel upcoming"><div class="section-heading"><div><h2>Les prochaines étapes</h2><p>Au premier terme atteint : date ou kilométrage.</p></div>${button('nav','Tout voir','arrow','text','data-page="parts"')}</div>${upcoming.length?`<div class="table-wrap"><table><thead><tr><th>PIÈCE / ENTRETIEN</th><th>ÉTAT</th><th>PROCHAINE ÉCHÉANCE</th><th></th></tr></thead><tbody>${upcoming.map(p=>`<tr><td><div class="part-cell"><span class="mini-icon">${icon('wrench')}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.category)}</small></div></div></td><td>${dueLabel(p,v)}</td><td>${remaining(p,v)}</td><td>${button('service','Consigner','plus','small secondary',`data-id="${esc(p.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Aucun rappel pour le moment.</p>'+button('add-part','Ajouter un premier rappel') }</section><div class="two-cards"><article class="panel compact-feature"><span class="feature-icon">${icon('book')}</span><div><h3>Un carnet qui suit votre histoire.</h3><p>Factures et interventions, pièce par pièce.</p></div>${button('nav','Ouvrir','arrow','text','data-page="book"')}</article><article class="panel compact-feature"><span class="feature-icon amber">${icon('pin')}</span><div><h3>Le bon plein, au bon endroit.</h3><p>Comparez les prix officiels autour de vous.</p></div>${button('nav','Rechercher','arrow','text','data-page="stations"')}</article></div><section class="panel technical-panel"><div class="section-heading"><div><h2>Repères pour ce véhicule</h2><p>Informations propres à la version et à votre carte grise.</p></div>${button('edit-vehicle','Compléter la fiche','arrow','text')}</div><div class="technical-grid"><div><span>Motorisation / version</span><strong>${esc(v.version||'À renseigner')}</strong></div><div><span>Pneumatiques</span><strong>${esc(v.specs.tires||'À relever sur le véhicule / la notice')}</strong></div><div><span>Ampoules</span><strong>${esc(v.specs.bulbs||'À confirmer selon les optiques')}</strong></div><div><span>Huile / norme</span><strong>${esc(v.specs.oil||'À confirmer dans la notice')}</strong></div><div><span>Transmission</span><strong>${esc(v.specs.transmission||'À renseigner')}</strong></div><div><span>Carte grise</span><strong>${v.registrationDocument?`<button class="btn text small" data-action="registration-document">${icon('file')}${esc(v.registrationDocument.name)}</button>`:'Document non ajouté'}</strong></div></div><p class="hint">${esc(v.specs.source||'Vérifiez chaque référence et périodicité dans la notice correspondant à votre moteur et à votre année.')}</p></section>`;
}
function partsPage(v:Vehicle){const p=parts().filter(x=>(filter==='all'||due(x,v.odometer,today(),vault!.settings.leadDays,vault!.settings.leadKm).status===filter)&&(x.name+' '+x.reference+' '+x.category).toLowerCase().includes(search.toLowerCase()));return title('L’ENTRETIEN SANS L’OUBLI','Pièces & échéances','Des rappels selon le temps et les kilomètres. Le premier terme atteint compte.',button('add-part','Ajouter une pièce'))+`<div class="list-toolbar">${vehicleSelect()}<div class="search-bar">${icon('search')}<input id="list-search" value="${esc(search)}" placeholder="Pièce ou référence…" aria-label="Rechercher une pièce"></div><select id="part-filter" aria-label="Filtrer les échéances"><option value="all" ${filter==='all'?'selected':''}>Toutes les échéances</option><option value="overdue" ${filter==='overdue'?'selected':''}>À faire</option><option value="soon" ${filter==='soon'?'selected':''}>Bientôt</option><option value="ok" ${filter==='ok'?'selected':''}>À jour</option></select></div><div class="notice">${icon('file')}Les intervalles sont ceux que vous définissez. Les pièces d’usure nécessitent un contrôle ; leur durée de vie n’est pas garantie.</div><div class="part-grid">${p.map(x=>`<article class="panel part-card"><div class="part-card-top"><span class="mini-icon">${icon('wrench')}</span>${dueLabel(x,v)}</div><span class="eyebrow">${esc(x.category)}</span><h3>${esc(x.name)}</h3><p class="reference">${esc(x.reference||'Référence à renseigner')}</p>${remaining(x,v)}<div class="part-details"><span>Dernier entretien</span><strong>${date(x.lastDate)} · ${n(x.lastKm)} km</strong><span>Périodicité personnelle</span><strong>${[x.intervalKm?n(x.intervalKm)+' km':'',x.intervalMonths?x.intervalMonths+' mois':''].filter(Boolean).join(' / ')}</strong><span>Source</span><strong>${esc(x.source||'À confirmer avec la notice constructeur')}</strong></div><div class="card-actions">${button('service','Consigner','plus','primary small',`data-id="${esc(x.id)}"`)}${button('edit-part','Modifier','wrench','text small',`data-id="${esc(x.id)}"`)}<button class="icon-btn" data-action="delete-part" data-id="${esc(x.id)}" aria-label="Supprimer ${esc(x.name)}">${icon('close')}</button></div></article>`).join('')}</div>${!p.length?empty('Aucune pièce ici.','Ajoutez une pièce ou modifiez votre recherche.','add-part','Ajouter une pièce'):''}`;}
function bookPage(v:Vehicle){const list=services().filter(s=>(s.title+' '+s.garage+' '+s.notes).toLowerCase().includes(search.toLowerCase()));return title('CHAQUE INTERVENTION COMPTE','Carnet d’entretien dématérialisé','L’historique de vos pièces, avec vos factures et justificatifs.',button('service','Ajouter une intervention'))+`<div class="list-toolbar">${vehicleSelect()}<div class="search-bar">${icon('search')}<input id="list-search" value="${esc(search)}" placeholder="Intervention, garage…" aria-label="Rechercher une intervention"></div></div><div class="book-summary"><strong>${services().length}</strong> interventions <span>·</span><strong>${money(services().reduce((n,s)=>n+s.cost,0))}</strong> d’entretien enregistré</div><div class="timeline">${list.map(s=>`<article class="panel service-card"><div class="service-date">${icon('check')}<span>${date(s.date)}</span></div><div class="service-main"><div class="section-heading"><h3>${esc(s.title)}</h3><strong class="service-cost">${money(s.cost)}</strong></div><p>${n(s.km)} km ${s.garage?'· '+esc(s.garage):''}</p>${s.notes?`<p class="service-notes">${esc(s.notes)}</p>`:''}<div class="attachments">${s.attachments.map(a=>`<button class="attachment" data-action="attachment" data-service="${esc(s.id)}" data-id="${esc(a.id)}">${icon('file')}${esc(a.name)}${icon('download')}</button>`).join('')}</div><div class="card-actions">${button('edit-service','Modifier','wrench','text small',`data-id="${esc(s.id)}"`)}<button class="btn text small danger" data-action="delete-service" data-id="${esc(s.id)}">Supprimer</button></div></div></article>`).join('')}</div>${!list.length?empty('Le début de votre historique.','Ajoutez une intervention et associez-y ses justificatifs.','service','Ajouter une intervention'):''}`;}
function fuelPage(v:Vehicle){const list=[...fills()].sort((a,b)=>b.km-a.km),stats=fuelStats(list);const max=Math.max(...stats.points.map(p=>p.value),10);return title('COMPRENDRE CHAQUE KILOMÈTRE','Votre consommation','Pleins, budget et consommation réelle, sans calcul à la main.',button('add-fill','Ajouter un plein'))+vehicleSelect()+`<div class="stats-grid fuel-stats"><article class="stat-card"><span class="stat-icon teal">${icon('fuel')}</span><div><span>Moyenne pondérée</span><strong>${stats.average===null?'—':new Intl.NumberFormat(languageTag(),{minimumFractionDigits:2,maximumFractionDigits:2}).format(stats.average)}<small> L/100 km</small></strong></div></article><article class="stat-card"><span class="stat-icon amber">${icon('chart')}</span><div><span>Carburant enregistré</span><strong>${money(stats.cost)}</strong></div></article><article class="stat-card"><span class="stat-icon blue">${icon('car')}</span><div><span>Distance calculable</span><strong>${n(stats.totalKm)}<small> km</small></strong></div></article><article class="stat-card"><span class="stat-icon violet">${icon('fuel')}</span><div><span>Volume enregistré</span><strong>${stats.totalLitres.toFixed(1)}<small> L</small></strong></div></article></div><section class="panel"><div class="section-heading"><div><h2>Au fil des pleins</h2><p>Calcul entre deux pleins complets ; les pleins partiels intermédiaires sont inclus.</p></div></div>${stats.points.length?`<div class="fuel-chart">${stats.points.slice(-12).map(p=>`<div class="chart-col"><strong>${p.value.toFixed(1)}</strong><div style="height:${Math.max(8,p.value/max*130)}px"></div><span>${date(p.date)}</span></div>`).join('')}</div>`:'<p class="muted">Ajoutez au moins deux pleins complets à des kilométrages différents pour calculer la consommation.</p>'}</section><section class="panel"><div class="section-heading"><h2>Historique des pleins</h2></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>KILOMÉTRAGE</th><th>VOLUME</th><th>MONTANT</th><th>TYPE</th><th></th></tr></thead><tbody>${list.map(f=>`<tr><td><strong>${date(f.date)}</strong><small>${esc(f.station)}</small></td><td>${n(f.km)} km</td><td>${f.litres.toFixed(2)} L</td><td>${money(f.cost)}<small>${(f.cost/f.litres).toFixed(3)} €/L</small></td><td><span class="badge ${f.full?'ok':'soon'}">${f.full?'Complet':'Partiel'}</span></td><td>${button('edit-fill','Modifier','wrench','text small',`data-id="${esc(f.id)}"`)}<button class="icon-btn" data-action="delete-fill" data-id="${esc(f.id)}" aria-label="Supprimer ce plein">${icon('close')}</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function foldersPage(){
 const folder=vault!.folders.find(x=>x.id===folderViewId);
 const q=search.toLowerCase().trim();
 const cars=vault!.vehicles.filter(v=>(folderViewId==='unfiled'?!v.folderId:folder? v.folderId===folder.id:true)&&[v.make,v.model,v.version,v.registration,v.vin,v.owner].some(x=>x.toLowerCase().includes(q)));
 const all=folderViewId==='unfiled'?vault!.vehicles.filter(v=>!v.folderId):folder?vault!.vehicles.filter(v=>v.folderId===folder.id):vault!.vehicles;
 const alerts=all.reduce((count,v)=>count+vault!.parts.filter(p=>p.vehicleId===v.id&&due(p,v.odometer,today(),vault!.settings.leadDays,vault!.settings.leadKm).status!=='ok').length,0);
 const serviceList=vault!.services.filter(s=>all.some(v=>v.id===s.vehicleId));
 const buttons=`${button('add-folder','Nouveau dossier','plus','secondary')}${button('add-vehicle','Ajouter un véhicule','plus')}`;
 return title('UN GARAGE BIEN ORGANISÉ',folder?folder.name:folderViewId==='unfiled'?'Véhicules sans dossier':'Dossiers & parc',folder?`${folder.clientName||'Dossier'} · ${folder.contact||'Coordonnées à renseigner'}`:'Regroupez les véhicules par client, foyer ou parc. Toutes les informations restent chiffrées.',buttons)+`<div class="folder-tabs"><button data-action="folder-open" data-id="" class="${!folderViewId?'active':''}">Tous les véhicules <b>${vault!.vehicles.length}</b></button>${vault!.folders.map(f=>`<button data-action="folder-open" data-id="${esc(f.id)}" class="${folderViewId===f.id?'active':''}">${esc(f.name)} <b>${vault!.vehicles.filter(v=>v.folderId===f.id).length}</b></button>`).join('')}<button data-action="folder-open" data-id="unfiled" class="${folderViewId==='unfiled'?'active':''}">Sans dossier <b>${vault!.vehicles.filter(v=>!v.folderId).length}</b></button></div>${folder?`<div class="folder-profile panel"><div><span class="eyebrow">FICHE DOSSIER</span><h2>${esc(folder.clientName||folder.name)}</h2><p>${esc(folder.contact||'Aucune coordonnée renseignée')}</p>${folder.notes?`<p>${esc(folder.notes)}</p>`:''}</div>${button('edit-folder','Modifier le dossier','wrench','secondary',`data-id="${esc(folder.id)}"`)}</div>`:''}<div class="stats-grid"><article class="stat-card"><span class="stat-icon teal">${icon('car')}</span><div><span>Véhicules</span><strong>${all.length}</strong></div></article><article class="stat-card"><span class="stat-icon amber">${icon('clock')}</span><div><span>Échéances à suivre</span><strong>${alerts}</strong></div></article><article class="stat-card"><span class="stat-icon blue">${icon('book')}</span><div><span>Interventions</span><strong>${serviceList.length}</strong></div></article><article class="stat-card"><span class="stat-icon violet">${icon('chart')}</span><div><span>Entretien</span><strong>${money(serviceList.reduce((n,s)=>n+s.cost,0))}</strong></div></article></div><div class="search-bar">${icon('search')}<input id="folder-search" value="${esc(search)}" placeholder="Rechercher marque, modèle, immatriculation, VIN ou titulaire…" aria-label="Rechercher dans le parc"></div><div class="fleet-grid">${cars.map(v=>{const dueParts=vault!.parts.filter(p=>p.vehicleId===v.id&&due(p,v.odometer,today(),vault!.settings.leadDays,vault!.settings.leadKm).status!=='ok');const f=vault!.folders.find(x=>x.id===v.folderId);return `<article class="panel fleet-card"><div class="section-heading"><span class="mini-icon">${icon('car')}</span><span class="badge ${dueParts.length?'soon':'ok'}">${dueParts.length?dueParts.length+' échéance(s)':'À jour'}</span></div><div class="eyebrow">${esc(f?.name||'SANS DOSSIER')} · ${v.year}</div><h3>${esc(v.make)} ${esc(v.model)}</h3><p>${esc(v.version)}</p><div class="fleet-meta"><span>${esc(v.registration||'Sans immatriculation')}</span><strong>${n(v.odometer)} km</strong></div><div class="card-actions">${button('fleet-select','Ouvrir la fiche','arrow','primary small',`data-id="${esc(v.id)}"`)}${button('edit-vehicle','Modifier','wrench','text small',`data-id="${esc(v.id)}"`)}</div></article>`;}).join('')}</div>${!cars.length?'<div class="empty-state"><h2>Aucun véhicule dans cette vue.</h2><p>Ajoutez un véhicule ou changez votre recherche.</p></div>':''}`;
}
function settingsPage(){return title('VOTRE GARAGE VOUS APPARTIENT','Paramètres & sauvegardes','Gardez la maîtrise de vos données et de vos rappels.')+`<div class="two-cards"><section class="panel"><span class="feature-icon">${icon('lock')}</span><h2>Un coffre personnel</h2><p>Véhicules, carte grise, interventions, pièces jointes et modèles importés sont chiffrés ensemble avec AES-256-GCM. La clé est dérivée de votre mot de passe avec PBKDF2-SHA-256, 600 000 itérations.</p><p class="hint">Verrouillage automatique après 10 minutes d’inactivité. Le chiffrement protège les fichiers au repos ; un appareil compromis ou un coffre ouvert reste exposé. Le mot de passe ne peut pas être récupéré.</p>${button('change-password','Changer de mot de passe','lock','secondary')}</section><section class="panel"><span class="feature-icon">${icon('download')}</span><h2>Vos sauvegardes</h2><p>Exportez un fichier .jmeca chiffré contenant tout le garage et ses pièces jointes. Rangez-le sur un autre support.</p><div class="stack-actions">${button('backup','Exporter le coffre chiffré','download')}${button('restore','Restaurer une sauvegarde','file','secondary')}</div><p class="hint">La restauration remplace le garage. Une sauvegarde de l’état actuel vous sera proposée avant de continuer.</p></section><section class="panel"><h2>Anticiper les échéances</h2><p>Les rappels apparaissent dans le logiciel lorsqu’il est ouvert.</p><form id="settings-form" class="form-grid">${field('Préavis en jours','leadDays',vault!.settings.leadDays,'number','min="0" max="365" required')}${field('Préavis en kilomètres','leadKm',vault!.settings.leadKm,'number','min="0" max="9999999" required')}<button class="btn primary" type="submit">Enregistrer</button></form></section><section class="panel"><h2>À propos de cette version</h2><p>JMeca 0.1.1 · Première version de test. Rust / Tauri et interface TypeScript. Aucun compte, aucune télémétrie.</p><p class="hint">Catalogue ADEME sous Licence Ouverte. Modèles Kenney sous CC0. Les silhouettes génériques ne reproduisent pas un modèle de marque. Pas de base certifiée de références de pièces ou de périodicités constructeur dans cette version.</p><div class="source-links"><a href="https://data.ademe.fr/datasets/ademe-car-labelling" target="_blank" rel="noreferrer">Catalogue ADEME ↗</a><a href="https://kenney.nl/assets/car-kit" target="_blank" rel="noreferrer">Modèles Kenney ↗</a></div></section></div>`;}
function stationsPage(){return title('LE BON PLEIN, AU BON ENDROIT','Recherche de stations essences','Prix officiels en France, triés du moins cher au plus cher.')+`<div class="notice">${icon('pin')}Recherche par code postal ou dans un rayon de 20 km autour de votre position. Seule cette recherche est transmise au service officiel.</div><section class="panel"><form id="stations-form" class="station-form">${field('Code postal français','postcode','','text','pattern="[0-9]{5}" maxlength="5" inputmode="numeric" placeholder="75012" required')}${select('Carburant','fuel',[{value:'gazole',label:'Gazole'},{value:'e10',label:'SP95-E10'},{value:'sp98',label:'SP98'},{value:'sp95',label:'SP95'},{value:'e85',label:'E85'},{value:'gplc',label:'GPLc'}])}<button class="btn primary" type="submit">${icon('search')}Rechercher</button>${button('geolocate','Autour de moi','pin','secondary')}</form><p class="hint">Les prix déclarés peuvent avoir changé. Vérifiez la date de mise à jour et les ruptures éventuelles. Les stations sans prix du carburant choisi sont exclues.</p></section><div id="station-results" aria-live="polite"><div class="empty-state">${icon('pin')}<h2>Votre prochain plein commence ici.</h2><p>Saisissez un code postal pour comparer les stations.</p></div></div><p class="source-line">Source : Ministère de l’Économie · prix-des-carburants-en-france-flux-instantane-v2 · Licence Ouverte. Intégration indépendante d’Essence&Co.</p>`;}
function bindFilters(){document.querySelector('#vehicle-select')?.addEventListener('change',e=>{selected=(e.target as HTMLSelectElement).value;render();});const input=document.querySelector<HTMLInputElement>('#list-search');input?.addEventListener('input',()=>{const start=input.selectionStart;search=input.value;render();const next=document.querySelector<HTMLInputElement>('#list-search');next?.focus();next?.setSelectionRange(start,start);});document.querySelector<HTMLInputElement>('#folder-search')?.addEventListener('input',e=>{search=(e.target as HTMLInputElement).value;const caret=(e.target as HTMLInputElement).selectionStart;render();const input=document.querySelector<HTMLInputElement>('#folder-search');input?.focus();input?.setSelectionRange(caret,caret);});document.querySelector('#part-filter')?.addEventListener('change',e=>{filter=(e.target as HTMLSelectElement).value;render();});document.querySelector('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();try{const d=new FormData(e.target as HTMLFormElement);await mutate(v=>{v.settings={leadDays:Number(d.get('leadDays')),leadKm:Number(d.get('leadKm'))};});toast('Préavis enregistrés.');}catch(e){toast(errorText(e),true);}});}
async function loadCatalogue(){try{if(!catalogue){const res=await fetch('/catalogue.json');if(!res.ok)throw Error('Catalogue indisponible.');catalogue=await res.json();}if(page!=='knowledge')return;renderCatalogue();document.querySelector<HTMLInputElement>('#catalogue-search')?.addEventListener('input',e=>{search=(e.target as HTMLInputElement).value;renderCatalogue();});}catch(e){const host=document.querySelector('#catalogue-results');if(host)host.textContent=errorText(e);}}
function renderCatalogue(){const host=document.querySelector('#catalogue-results');if(!host||!catalogue)return;const words=search.toLocaleLowerCase().split(/\s+/).filter(Boolean);const rows=catalogue.vehicles.filter(r=>words.every(w=>(r.make+' '+r.model+' '+r.version+' '+r.energy+' '+r.cc).toLowerCase().includes(w)));const count=catalogue.count,makes=new Set(catalogue.vehicles.map(r=>r.make)).size;host.innerHTML=`<div class="catalogue-info"><strong>${n(count)} versions · ${makes} marques</strong><span>${n(rows.length)} résultats · ${rows.length>60?'60 affichés · affinez votre recherche':''}</span></div><p class="hint">Source ADEME Car Labelling · catalogue du marché du neuf, non exhaustif pour les véhicules anciens. Données téléchargées le ${date(catalogue.retrieved.slice(0,10))}. La version commerciale, la puissance et la cylindrée aident à identifier le moteur ; le code moteur et la finition peuvent nécessiter un complément manuel.</p><div class="catalogue-grid">${rows.slice(0,60).map(r=>`<article class="panel catalogue-card"><div class="eyebrow">${esc(r.make)}</div><h3>${esc(r.model)}</h3><p>${esc(r.version)}</p><div class="catalogue-tags"><span>${esc(r.energy)}</span>${r.cc?`<span>${r.cc} cm³</span>`:''}${r.kw?`<span>${r.kw} kW</span>`:''}<span>${esc(r.gearbox)}</span></div>${button('catalogue-add','Choisir cette version','plus','text small',`data-id="${esc(r.id)}"`)}</article>`).join('')}</div>${!rows.length?'<p class="muted">Aucun résultat. Vous pouvez ajouter votre véhicule manuellement.</p>':''}`;translateDOM(host);}
function bindStations(){document.querySelector('#stations-form')?.addEventListener('submit',e=>{e.preventDefault();void queryStations();});}
let stationBusy=false;
async function queryStations(position?:{lat:number;lon:number}){
 const form=document.querySelector<HTMLFormElement>('#stations-form'),host=document.querySelector('#station-results');if(!form||!host||stationBusy)return;const d=new FormData(form),fuel=String(d.get('fuel')),postcode=String(d.get('postcode'));if(!position&&!/^\d{5}$/.test(postcode)){toast('Indiquez un code postal à 5 chiffres.',true);return;}
 stationBusy=true;host.innerHTML='<div class="panel"><p class="muted">Recherche des prix officiels…</p></div>';const token=session;
 try{let result:{results:Station[];total:number};if(storage.native){result=await storage.invoke('search_stations',{postcode,fuel,lat:position?.lat??null,lon:position?.lon??null});}else{const u=new URL('https://data.economie.gouv.fr/api/explore/v2.1/catalog/datasets/prix-des-carburants-en-france-flux-instantane-v2/records');u.searchParams.set('where',`(${position?`within_distance(geom, GEOM'POINT(${position.lon} ${position.lat})', 20km)`:`cp = '${postcode}'`}) AND ${fuel}_prix IS NOT NULL`);u.searchParams.set('order_by',fuel+'_prix ASC');u.searchParams.set('limit','30');const r=await fetch(u,{signal:AbortSignal.timeout(20000),referrerPolicy:'no-referrer'});if(!r.ok)throw Error('Le service des stations est momentanément indisponible.');const data=await r.json();result={results:data.results.map((s:Record<string,unknown>)=>({id:s.id,address:s.adresse,city:s.ville,postcode:s.cp,price:s[fuel+'_prix'],updated:s[fuel+'_maj'],outage:s[fuel+'_rupture_debut'],location:s.geom,services:s.services_service})),total:data.total_count};}
 if(session!==token||page!=='stations')return;
 const out=document.querySelector('#station-results')!;
 out.innerHTML=`<div class="section-heading"><h2>${result.results.length} station${result.results.length>1?'s':''} affichée${result.results.length>1?'s':''}</h2><span class="muted">${result.total} résultat(s) · du moins cher au plus cher</span></div><div class="station-grid">${result.results.map((s,i)=>`<article class="panel station-card"><div class="section-heading"><span class="badge ${s.outage?'overdue':i===0?'ok':'neutral'}">${s.outage?'Rupture signalée':i===0?'Le moins cher':'Prix déclaré'}</span><strong class="station-price">${Number(s.price).toFixed(3).replace('.',',')}<small> €/L</small></strong></div><h3>${esc(s.city)}</h3><p>${esc(s.address)} · ${esc(s.postcode)}</p><p class="hint">Mis à jour : ${s.updated?esc(new Date(s.updated).toLocaleString(languageTag())):'date non fournie'}</p>${Array.isArray(s.services)?`<p class="hint">${esc(s.services.slice(0,5).join(' · '))}</p>`:''}${s.location&&Number.isFinite(s.location.lat)&&Number.isFinite(s.location.lon)?`<a class="btn text small" href="https://www.openstreetmap.org/?mlat=${s.location.lat}&mlon=${s.location.lon}#map=16/${s.location.lat}/${s.location.lon}" target="_blank" rel="noreferrer">Voir sur la carte ↗</a>`:''}</article>`).join('')}</div>${result.results.length?'':'<div class="panel"><p>Aucune station correspondante. Essayez un code postal voisin ou un autre carburant.</p></div>'}`;translateDOM(out);
 }catch(e){if(session===token&&page==='stations'){const out=document.querySelector('#station-results');if(out){out.innerHTML=`<div class="panel"><h3>Recherche indisponible</h3><p>${esc(errorText(e))}</p><p class="hint">Le reste de JMeca reste accessible hors ligne.</p></div>`;}}}finally{stationBusy=false;}
}
interface Station{id:string;address:string;city:string;postcode:string;price:number;updated:string;outage:unknown;location:{lat:number;lon:number}|null;services:string[]|null;}
function dialog(title:string,content:string,onSubmit:(d:FormData,form:HTMLFormElement)=>Promise<void>,submit='Enregistrer'){
 document.querySelector('dialog')?.remove();const el=document.createElement('dialog');el.className='modal';el.innerHTML=`<form method="dialog" class="modal-form"><div class="modal-header"><h2>${title}</h2><button class="icon-btn" type="button" data-close aria-label="Fermer">${icon('close')}</button></div><div class="modal-body form-grid">${content}</div><p class="form-error" role="alert"></p><div class="modal-footer"><button class="btn secondary" type="button" data-close>Annuler</button><button class="btn primary" type="submit">${submit}</button></div></form>`;document.body.append(el);el.showModal();translateDOM(el);el.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>el.remove()));el.addEventListener('click',e=>{if(e.target===el)el.remove();});el.addEventListener('close',()=>el.remove());el.querySelector('form')!.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget as HTMLFormElement;const submit=form.querySelector<HTMLButtonElement>('[type="submit"]')!;if(submit.disabled)return;submit.disabled=true;el.querySelector('.form-error')!.textContent='';try{await onSubmit(new FormData(form),form);el.remove();render();}catch(e){el.querySelector('.form-error')!.textContent=errorText(e);submit.disabled=false;}});return el;
}
const get=(d:FormData,k:string)=>String(d.get(k)??'').trim();const num=(d:FormData,k:string)=>Number(d.get(k));
function blankVehicle():Vehicle{return {id:uid(),folderId:'',make:'',model:'',version:'',year:new Date().getFullYear(),energy:'ESSENCE',odometer:0,registration:'',vin:'',owner:'',registrationDate:'',notes:'',model3d:'sedan',color:'#2d7873',specs:{tires:'',bulbs:'',oil:'',transmission:'',source:''}};}
function vehicleDialog(existing?:Vehicle,row?:CatalogueRow){
 const v=existing??blankVehicle();if(!existing&&folderViewId&&folderViewId!=='unfiled')v.folderId=folderViewId;if(row){Object.assign(v,{make:row.make,model:row.model,version:row.version,energy:row.energy});v.specs.transmission=row.gearbox;v.specs.source='ADEME Car Labelling · '+row.id;}
 const el=dialog(existing?'Fiche véhicule':'Ajouter un véhicule',`<p class="full hint">${row?'Version sélectionnée dans le catalogue ADEME. Complétez les informations propres à votre véhicule.':'Renseignez votre véhicule. Les informations de carte grise restent dans votre coffre chiffré.'}</p>${field('Marque','make',v.make,'text','required maxlength="100"')}${field('Modèle','model',v.model,'text','required maxlength="100"')}${select('Dossier','folderId',[{value:'',label:'Sans dossier'},...vault!.folders.map(f=>({value:f.id,label:f.name}))],v.folderId)}${field('Version / moteur / finition','version',v.version,'text','maxlength="300"')}${field('Année','year',v.year,'number','min="1900" max="2100" required')}${field('Énergie','energy',v.energy,'text','required maxlength="100"')}${field('Kilométrage actuel','odometer',v.odometer,'number',`min="${existing?v.odometer:0}" max="9999999" required`)}<h3 class="full form-section">Carte grise · données chiffrées</h3>${field('Immatriculation (A)','registration',v.registration,'text','maxlength="100"')}${field('N° de série VIN (E)','vin',v.vin,'text','maxlength="100"')}${field('Titulaire (C.1)','owner',v.owner,'text','maxlength="200"')}${field('Première immatriculation (B)','registrationDate',v.registrationDate,'date')}<label class="field full">Document carte grise (PDF ou image, 10 Mo max.)<input name="registrationDocument" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp"><span class="hint">${v.registrationDocument?esc(v.registrationDocument.name):'Optionnel · conservé chiffré dans la fiche véhicule'}</span></label>${v.registrationDocument?'<label class="checkbox full"><input type="checkbox" name="removeRegistrationDocument">Retirer le document actuel</label>':''}<h3 class="full form-section">Informations utiles · à vérifier sur la notice</h3>${field('Dimensions des pneus','tires',v.specs.tires,'text','maxlength="300"')}${field('Ampoules / optiques','bulbs',v.specs.bulbs,'text','maxlength="300"')}${field('Huile / norme constructeur','oil',v.specs.oil,'text','maxlength="300"')}${field('Boîte / transmission','transmission',v.specs.transmission,'text','maxlength="300"')}${field('Source et version de la notice','source',v.specs.source,'text','maxlength="500"')}<h3 class="full form-section">Votre aperçu 3D</h3>${select('Silhouette générique Kenney · CC0','model3d',[['sedan','Berline'],['hatchback-sports','Compacte sportive'],['suv','SUV'],['suv-luxury','SUV premium'],['truck','Pick-up'],['van','Monospace / van'],['sedan-sports','Berline sportive'],['race','Voiture de course'],['taxi','Taxi']].map(([value,label])=>({value,label})),v.model3d)}<label class="field">Importer un modèle GLB autonome (10 Mo max.)<input name="customModel" type="file" accept=".glb"><span class="hint">${v.customModel?esc(v.customModel.name):'Optionnel. Utilisez un modèle dont vous détenez les droits.'}</span></label>${v.customModel?'<label class="checkbox full"><input type="checkbox" name="removeModel">Revenir à la silhouette générique</label>':''}${area('Notes','notes',v.notes)}${existing?`<button class="btn text danger full" type="button" data-action="delete-vehicle" data-id="${esc(v.id)}">Supprimer ce véhicule et son historique…</button>`:''}`,async d=>{
 const updated:Vehicle={...v,folderId:get(d,'folderId'),make:get(d,'make'),model:get(d,'model'),version:get(d,'version'),year:num(d,'year'),energy:get(d,'energy'),odometer:num(d,'odometer'),registration:get(d,'registration'),vin:get(d,'vin'),owner:get(d,'owner'),registrationDate:get(d,'registrationDate'),notes:get(d,'notes'),model3d:get(d,'model3d'),specs:{tires:get(d,'tires'),bulbs:get(d,'bulbs'),oil:get(d,'oil'),transmission:get(d,'transmission'),source:get(d,'source')}};
 const documentFile=(await readAttachments(d.getAll('registrationDocument')))[0];if(d.get('removeRegistrationDocument'))delete updated.registrationDocument;if(documentFile)updated.registrationDocument=documentFile;const file=d.get('customModel');if(d.get('removeModel'))delete updated.customModel;if(file instanceof File&&file.size){const bytes=new Uint8Array(await file.arrayBuffer());validateGLB(bytes);updated.customModel={id:uid(),name:file.name,mime:'model/gltf-binary',data:toB64(bytes)};}
 vehicleSchema.parse(updated);if(existing&&updated.odometer<existing.odometer)throw Error('Le kilométrage ne peut pas diminuer.');await mutate(state=>{if(existing)state.vehicles[state.vehicles.findIndex(x=>x.id===v.id)]=updated;else state.vehicles.push(updated);});selected=v.id;toast('Véhicule enregistré.');});
 return el;
}
function folderDialog(existing?:Folder){const f=existing??{id:uid(),name:'',clientName:'',contact:'',notes:''};dialog(existing?'Modifier un dossier':'Nouveau dossier',`${field('Nom du dossier','name',f.name,'text','required maxlength="120" placeholder="Ex. Atelier Dupont, Famille Martin…"')}${field('Client / responsable','clientName',f.clientName,'text','maxlength="200"')}${field('Téléphone ou e-mail','contact',f.contact,'text','maxlength="300"')}${area('Notes internes','notes',f.notes)}<p class="hint full">Les coordonnées et notes restent dans le coffre chiffré. La suppression d’un dossier conserve les véhicules et leur historique.</p>${existing?`<button class="btn text danger full" type="button" data-action="delete-folder" data-id="${esc(f.id)}">Supprimer ce dossier…</button>`:''}`,async d=>{const value:Folder={...f,name:get(d,'name'),clientName:get(d,'clientName'),contact:get(d,'contact'),notes:get(d,'notes')};if(!value.name)throw Error('Indiquez un nom de dossier.');await mutate(v=>{if(existing)v.folders[v.folders.findIndex(x=>x.id===f.id)]=value;else v.folders.push(value);});folderViewId=f.id;page='folders';toast('Dossier enregistré.');});}
function partDialog(existing?:Part){const v=vehicle();if(!v)return;const p=existing??{id:uid(),vehicleId:v.id,name:'',category:'Moteur',reference:'',lastDate:today(),lastKm:v.odometer,intervalKm:0,intervalMonths:0,notes:'',source:''};
 const el=dialog(existing?'Modifier une pièce':'Ajouter une pièce ou un rappel',`<p class="hint full">Saisissez les périodicités de la notice correspondant à votre moteur. 0 désactive un des deux critères. Les modèles ci-dessous servent uniquement à choisir le nom de l’opération.</p>${select('Modèle de rappel','template',[{value:'',label:'Personnalisé'},...partTemplates.map(([name,category])=>({value:name,label:name+' · '+category}))])}${field('Pièce / opération','name',p.name,'text','required maxlength="200"')}${field('Catégorie','category',p.category,'text','maxlength="100"')}${field('Référence de pièce','reference',p.reference,'text','maxlength="300"')}${field('Dernière intervention','lastDate',p.lastDate,'date',`max="${today()}" required`)}${field('Kilométrage à cette date','lastKm',p.lastKm,'number',`min="0" max="${v.odometer}" required`)}${field('Tous les X km (0 = désactivé)','intervalKm',p.intervalKm,'number','min="0" max="9999999" required')}${field('Tous les X mois (12 = 1 an)','intervalMonths',p.intervalMonths,'number','min="0" max="1200" required')}${field('Source de la préconisation','source',p.source,'text','placeholder="Notice constructeur, page…" maxlength="500"')}${area('Notes','notes',p.notes)}`,async d=>{const value:Part={...p,name:get(d,'name'),category:get(d,'category'),reference:get(d,'reference'),lastDate:get(d,'lastDate'),lastKm:num(d,'lastKm'),intervalKm:num(d,'intervalKm'),intervalMonths:num(d,'intervalMonths'),source:get(d,'source'),notes:get(d,'notes')};if(!value.intervalKm&&!value.intervalMonths)throw Error('Renseignez une échéance en kilomètres ou en mois.');if(value.lastDate>today())throw Error('La dernière intervention ne peut pas être dans le futur.');partSchema.parse(value);await mutate(s=>{if(existing)s.parts[s.parts.findIndex(x=>x.id===p.id)]=value;else s.parts.push(value);});toast('Rappel enregistré.');});
 el.querySelector<HTMLSelectElement>('[name="template"]')!.addEventListener('change',e=>{const name=(e.target as HTMLSelectElement).value,template=partTemplates.find(x=>x[0]===name);if(template){el.querySelector<HTMLInputElement>('[name="name"]')!.value=name;el.querySelector<HTMLInputElement>('[name="category"]')!.value=template[1];}});
}
async function readAttachments(input:FormDataEntryValue[]):Promise<Attachment[]>{const out:Attachment[]=[];for(const file of input){if(!(file instanceof File)||!file.size)continue;if(file.size>10*1024*1024)throw Error('Chaque pièce jointe est limitée à 10 Mo.');const data=new Uint8Array(await file.arrayBuffer());const mime=file.type;let valid=false;if(mime==='application/pdf')valid=new TextDecoder().decode(data.subarray(0,5))==='%PDF-';if(mime==='image/png')valid=data[0]===137&&data[1]===80&&data[2]===78&&data[3]===71;if(mime==='image/jpeg')valid=data[0]===255&&data[1]===216&&data[2]===255;if(mime==='image/webp')valid=new TextDecoder().decode(data.subarray(0,4))==='RIFF'&&new TextDecoder().decode(data.subarray(8,12))==='WEBP';if(!valid)throw Error('Formats acceptés : PDF, PNG, JPEG et WebP valides.');out.push({id:uid(),name:file.name,mime:mime as Attachment['mime'],data:toB64(data)});}return out;}
function serviceDialog(partId='',existing?:Service){const v=vehicle();if(!v)return;const part=parts().find(p=>p.id===partId);const s=existing??{id:uid(),vehicleId:v.id,partId,title:part?.name??'',date:today(),km:v.odometer,cost:0,garage:'',notes:'',attachments:[]};
 const el=dialog(existing?'Modifier une intervention':'Consigner une intervention',`${field('Titre de l’intervention','title',s.title,'text','required maxlength="200"')}${select('Pièce concernée','partId',[{value:'',label:'Intervention libre'},...parts().map(p=>({value:p.id,label:p.name}))],s.partId)}${field('Date','date',s.date,'date',`required max="${today()}"`)}${field('Kilométrage','km',s.km,'number','min="0" max="9999999" required')}${field('Coût total (€)','cost',s.cost,'number','min="0" max="10000000" step="0.01" required')}${field('Garage / réalisé par','garage',s.garage,'text','maxlength="300"')}${area('Travaux réalisés et observations','notes',s.notes)}<label class="field full">Ajouter des justificatifs (PDF ou images, 10 Mo / fichier)<input type="file" name="attachments" accept=".pdf,.png,.jpg,.jpeg,.webp" multiple></label>${s.attachments.length?`<div class="full"><p class="hint">Pièces jointes conservées sauf si vous les cochez :</p>${s.attachments.map(a=>`<label class="checkbox"><input type="checkbox" name="remove" value="${esc(a.id)}"> Retirer ${esc(a.name)}</label>`).join('')}</div>`:''}${!existing?'<label class="checkbox full"><input name="renew" type="checkbox" checked>Recalculer les échéances de la pièce à partir de cette intervention</label>':'<p class="full hint">Modifier une intervention ne modifie pas automatiquement la dernière intervention de la pièce. Ajustez la pièce si nécessaire.</p>'}<p class="full hint">Une photo de carte grise peut aussi être conservée ici, avec un titre explicite. Tout le contenu est chiffré.</p>`,async d=>{
 const attachments=[...s.attachments.filter(a=>!d.getAll('remove').includes(a.id)),...await readAttachments(d.getAll('attachments'))];const value:Service={...s,title:get(d,'title'),partId:get(d,'partId'),date:get(d,'date'),km:num(d,'km'),cost:num(d,'cost'),garage:get(d,'garage'),notes:get(d,'notes'),attachments};if(value.date>today())throw Error('Une intervention ne peut pas être datée dans le futur.');serviceSchema.parse(value);await mutate(state=>{if(existing)state.services[state.services.findIndex(x=>x.id===s.id)]=value;else state.services.push(value);const car=state.vehicles.find(x=>x.id===v.id)!;car.odometer=Math.max(car.odometer,value.km);if(!existing&&value.partId&&d.get('renew')){const p=state.parts.find(x=>x.id===value.partId)!;if(value.km<p.lastKm||value.date<p.lastDate)throw Error('Cette intervention est antérieure à la dernière révision. Décochez le recalcul pour conserver l’historique.');p.lastDate=value.date;p.lastKm=value.km;}});toast('Intervention et justificatifs enregistrés.');});
 el.querySelector<HTMLSelectElement>('[name="partId"]')!.addEventListener('change',e=>{if(!el.querySelector<HTMLInputElement>('[name="title"]')!.value)el.querySelector<HTMLInputElement>('[name="title"]')!.value=parts().find(x=>x.id===(e.target as HTMLSelectElement).value)?.name??'';});
}
function fillDialog(existing?:Fill){const v=vehicle();if(!v)return;const f=existing??{id:uid(),vehicleId:v.id,date:today(),km:v.odometer,litres:0,cost:0,full:true,station:''};dialog(existing?'Modifier un plein':'Ajouter un plein',`${field('Date','date',f.date,'date',`max="${today()}" required`)}${field('Kilométrage','km',f.km,'number','min="0" max="9999999" required')}${field('Volume (litres)','litres',f.litres||'','number','min="0.01" max="1000" step="0.01" required')}${field('Montant total (€)','cost',f.cost||'','number','min="0" max="10000000" step="0.01" required')}${field('Station (facultatif)','station',f.station,'text','maxlength="300"')}<label class="checkbox full"><input name="full" type="checkbox" ${f.full?'checked':''}>Plein complet (réservoir rempli)</label><p class="hint full">Le premier plein complet établit le point de départ. Les pleins partiels suivants seront additionnés jusqu’au prochain plein complet.</p>`,async d=>{const value:Fill={...f,date:get(d,'date'),km:num(d,'km'),litres:num(d,'litres'),cost:num(d,'cost'),station:get(d,'station'),full:!!d.get('full')};if(value.date>today())throw Error('La date ne peut pas être dans le futur.');fillSchema.parse(value);const others=fills().filter(x=>x.id!==value.id);if(others.some(x=>x.km===value.km))throw Error('Un plein existe déjà à ce kilométrage. Modifiez-le ou indiquez le kilométrage exact.');if(others.some(x=>(x.date<value.date&&x.km>value.km)||(x.date>value.date&&x.km<value.km)))throw Error('Le kilométrage ne correspond pas à la chronologie des pleins.');await mutate(state=>{if(existing)state.fills[state.fills.findIndex(x=>x.id===f.id)]=value;else state.fills.push(value);const car=state.vehicles.find(x=>x.id===v.id)!;car.odometer=Math.max(car.odometer,value.km);});toast('Plein enregistré.');});}
async function restoreBackup(){const text=await storage.pickBackup();if(text===null)return;if(!text)throw Error('Sauvegarde trop volumineuse.');dialog('Restaurer le coffre',`<p class="full">Saisissez le mot de passe de la sauvegarde sélectionnée. Son intégrité et sa structure seront vérifiées avant le remplacement.</p>${field('Mot de passe de la sauvegarde','password','','password','required maxlength="256" autocomplete="off"')}<label class="checkbox full"><input type="checkbox" name="replace" required>Je confirme le remplacement du garage actuel.</label><p class="hint full">${envelope?'Une sauvegarde chiffrée du coffre actuel sera demandée avant le remplacement. Annuler son enregistrement interrompt la restauration.':'Le mot de passe de la sauvegarde deviendra celui de ce coffre.'}</p>`,async d=>{const result=await decryptVault(text,get(d,'password'));await saveQueue.catch(()=>{});if(envelope){const saved=await storage.exportEncrypted(envelope);if(!saved)throw Error('Restauration annulée : sauvegarde du coffre actuel non enregistrée.');}await storage.save(text);vault=result.vault;key=result.key;salt=result.salt;envelope=text;demo=false;session++;saveError=false;selected=vault.vehicles[0]?.id??'';lastActivity=Date.now();toast('Coffre restauré. Utilisez le mot de passe de cette sauvegarde.');},'Restaurer et remplacer');}
function exportOneAttachment(a:Attachment){dialog('Exporter un justificatif',`<p class="full">${esc(a.name)}</p><p class="full hint">Le fichier exporté sera déchiffré. Choisissez un emplacement de confiance.</p>`,async()=>{if(storage.native){const ok=await storage.invoke<boolean>('export_attachment',{name:a.name,data:a.data});if(!ok)throw Error('Export annulé.');}else{await storage.download(a.name,new Blob([fromB64(a.data) as BlobPart],{type:a.mime}));}},'Exporter le fichier');}
function confirmAction(title:string,detail:string,action:()=>Promise<void>){dialog(title,`<p class="full">${esc(detail)}</p><label class="checkbox full"><input name="confirm" type="checkbox" required>Je confirme cette suppression.</label>`,async()=>{await action();toast('Suppression enregistrée.');},'Supprimer');}
async function lock(){if(loading)return;loading=true;try{await saveQueue;if(saveError)throw Error('L’enregistrement a échoué. Réessayez avant de verrouiller.');session++;vault=null;key=null;salt=null;demo=false;selected='';page='dashboard';search='';filter='all';renderGate();}catch(e){toast(errorText(e),true);}finally{loading=false;}}
async function handleAction(action:string,el:HTMLElement){const id=el.dataset.id??'';switch(action){
 case 'nav':page=el.dataset.page??'dashboard';search='';filter='all';render();break;
 case 'demo':vault=demoVault();demo=true;selected=vault.vehicles[0].id;session++;page='dashboard';lastActivity=Date.now();render();break;
 case 'lock':await lock();break;
 case 'add-vehicle':vehicleDialog();break;
 case 'add-folder':folderDialog();break;
 case 'edit-folder':folderDialog(vault?.folders.find(f=>f.id===id));break;
 case 'folder-open':folderViewId=id;search='';page='folders';render();break;
 case 'fleet-select':selected=id;page='dashboard';search='';render();break;
 case 'edit-vehicle':vehicleDialog(id?vault?.vehicles.find(v=>v.id===id):vehicle());break;
 case 'catalogue-add':{const row=catalogue?.vehicles.find(x=>x.id===id);if(row)vehicleDialog(undefined,row);break;}
 case 'add-part':partDialog();break;
 case 'edit-part':partDialog(parts().find(x=>x.id===id));break;
 case 'service':serviceDialog(id);break;
 case 'edit-service':{const s=services().find(x=>x.id===id);if(s)serviceDialog(s.partId,s);break;}
 case 'add-fill':fillDialog();break;
 case 'edit-fill':fillDialog(fills().find(x=>x.id===id));break;
 case 'mileage':{const v=vehicle();if(!v)break;dialog('Mettre à jour le kilométrage',`${field('Kilométrage au compteur','odometer',v.odometer,'number',`min="${v.odometer}" max="9999999" required`)}<p class="hint full">La saisie ne peut pas être inférieure au kilométrage actuel. Vos rappels seront recalculés immédiatement.</p>`,async d=>{const km=num(d,'odometer');if(km<v.odometer)throw Error('Le kilométrage ne peut pas diminuer.');await mutate(s=>{s.vehicles.find(x=>x.id===v.id)!.odometer=km;});toast('Kilométrage mis à jour.');});break;}
 case 'delete-folder':confirmAction('Supprimer ce dossier ?', 'Les véhicules du dossier seront classés Sans dossier. Leurs pièces, interventions et justificatifs resteront dans le coffre.',async()=>{await mutate(s=>{s.folders=s.folders.filter(f=>f.id!==id);s.vehicles.forEach(v=>{if(v.folderId===id)v.folderId='';});});folderViewId='';});break;
 case 'delete-vehicle':confirmAction('Supprimer ce véhicule ?', 'Le véhicule, les pièces, interventions, justificatifs et pleins associés seront supprimés du coffre actuel. Vos anciennes sauvegardes les conservent.',async()=>{await mutate(s=>{s.vehicles=s.vehicles.filter(v=>v.id!==id);s.parts=s.parts.filter(v=>v.vehicleId!==id);s.services=s.services.filter(v=>v.vehicleId!==id);s.fills=s.fills.filter(v=>v.vehicleId!==id);});selected=vault!.vehicles[0]?.id??'';});break;
 case 'delete-part':confirmAction('Supprimer cette pièce ?','Ses interventions resteront dans le carnet, avec leur titre et leurs justificatifs.',async()=>{await mutate(s=>{s.parts=s.parts.filter(p=>p.id!==id);s.services.forEach(x=>{if(x.partId===id)x.partId='';});});});break;
 case 'delete-service':confirmAction('Supprimer cette intervention ?','L’intervention et ses pièces jointes seront supprimées. L’échéance de la pièce ne sera pas modifiée automatiquement.',async()=>{await mutate(s=>{s.services=s.services.filter(p=>p.id!==id);});});break;
 case 'delete-fill':confirmAction('Supprimer ce plein ?','La consommation sera recalculée. Le kilométrage du véhicule sera conservé.',async()=>{await mutate(s=>{s.fills=s.fills.filter(p=>p.id!==id);});});break;
 case 'registration-document':{const a=vehicle()?.registrationDocument;if(a)exportOneAttachment(a);break;}
 case 'attachment':{const a=services().find(s=>s.id===el.dataset.service)?.attachments.find(a=>a.id===id);if(a)exportOneAttachment(a);break;}
 case 'backup':if(demo){toast('La démonstration ne peut pas être sauvegardée. Créez un coffre pour conserver vos données.');break;}await saveQueue;if(envelope&&await storage.exportEncrypted(envelope))toast('Sauvegarde chiffrée exportée.');break;
 case 'restore-gate':case 'restore':if(demo){toast('Quittez la démonstration pour restaurer un coffre.');break;}await restoreBackup();break;
 case 'change-password':if(demo){toast('Créez un coffre personnel pour définir un mot de passe.');break;}dialog('Changer le mot de passe',`${field('Mot de passe actuel','current','','password','required autocomplete="current-password" maxlength="256"')}${field('Nouveau mot de passe','password','','password','required minlength="12" maxlength="256" autocomplete="new-password"')}${field('Confirmez le nouveau mot de passe','confirm','','password','required minlength="12" maxlength="256" autocomplete="new-password"')}<p class="hint full">Les sauvegardes précédentes gardent leur ancien mot de passe. Exportez une nouvelle sauvegarde après ce changement.</p>`,async d=>{await saveQueue;if(!envelope||!vault)throw Error('Coffre indisponible.');await decryptVault(envelope,get(d,'current'));const p=get(d,'password');if(p!==get(d,'confirm'))throw Error('Les nouveaux mots de passe ne correspondent pas.');const nextSalt=crypto.getRandomValues(new Uint8Array(16)),nextKey=await deriveKey(p,nextSalt);const encrypted=await encryptVault(vault,nextKey,nextSalt);await storage.save(encrypted);key=nextKey;salt=nextSalt;envelope=encrypted;toast('Mot de passe changé. Exportez une nouvelle sauvegarde.');});break;
 case 'geolocate':{if(!navigator.geolocation)throw Error('Géolocalisation indisponible. Utilisez un code postal.');navigator.geolocation.getCurrentPosition(p=>{void queryStations({lat:p.coords.latitude,lon:p.coords.longitude});},()=>toast('Position indisponible ou refusée. Utilisez un code postal.',true),{enableHighAccuracy:false,timeout:12000,maximumAge:300000});break;}
}}
document.addEventListener('change',e=>{const el=e.target as HTMLSelectElement;if(el.id==='language-select'){setLanguage(el.value);if(vault)render();else renderGate();}});
document.addEventListener('click',e=>{const el=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!el)return;e.preventDefault();void handleAction(el.dataset.action!,el).catch(e=>toast(errorText(e),true));});
let lastActivity=Date.now();for(const event of ['pointerdown','keydown','wheel','touchstart'])document.addEventListener(event,()=>{lastActivity=Date.now();},{passive:true});
setInterval(()=>{if(vault&&!demo&&!loading&&Date.now()-lastActivity>10*60*1000)void lock();},15000);
window.addEventListener('beforeunload',e=>{if(loading){e.preventDefault();}});
async function init(){try{envelope=await storage.load();renderGate();}catch(e){root.innerHTML=`<main class="gate"><h1>Coffre inaccessible</h1><p>${esc(errorText(e))}</p><p>Le coffre existant est conservé. Vous pouvez restaurer une sauvegarde .jmeca ou .jmeca.bak.</p>${button('restore-gate','Restaurer une sauvegarde','download')}${languageSelector()}</main>`;translateDOM(root);}}
void init();
